type relationshipWhere[Q psql.Filterable] struct {
	cols      relationshipColumns
	ID        psql.WhereMod[Q, string]
	CreatedAt psql.WhereMod[Q, time.Time]
	Metadata  psql.WhereMod[Q, types.JSON[map[string]any]]
	SourceID  psql.WhereMod[Q, string]
	TargetID  psql.WhereMod[Q, string]
	TypeID    psql.WhereNullMod[Q, string]
	Directed  psql.WhereMod[Q, bool]
	Version   psql.WhereMod[Q, int64]
	R         relationshipWhereR[Q]
}

func (relationshipWhere[Q]) AliasedAs(alias string) relationshipWhere[Q] {
	return buildRelationshipWhere[Q](buildRelationshipColumns(alias))
}

func buildRelationshipWhere[Q psql.Filterable](cols relationshipColumns) relationshipWhere[Q] {
	return relationshipWhere[Q]{
		cols:      cols,
		ID:        psql.Where[Q, string](cols.ID.Expression),
		CreatedAt: psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		Metadata:  psql.Where[Q, types.JSON[map[string]any]](cols.Metadata.Expression),
		SourceID:  psql.Where[Q, string](cols.SourceID.Expression),
		TargetID:  psql.Where[Q, string](cols.TargetID.Expression),
		TypeID:    psql.WhereNull[Q, string](cols.TypeID.Expression),
		Directed:  psql.Where[Q, bool](cols.Directed.Expression),
		Version:   psql.Where[Q, int64](cols.Version.Expression),
		R:         relationshipWhereR[Q]{cols: cols},
	}
}

// relationshipWhereR holds the relationship-based filters of
// relationshipWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type relationshipWhereR[Q psql.Filterable] struct {
	cols relationshipColumns
}

// HasSourceResource filters parents that have a matching SourceResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w relationshipWhereR[Q]) HasSourceResource(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Resources.NameExpr()),
		sm.Where(Resources.Columns.ID.EQ(w.cols.SourceID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

